public class Test {
    static int i = 0;
    int j = 1;

    public void TestMethod() {
        final int finalI = i;
        class TestInner {
            public void InnerMethod() {
                System.out.println(finalI);
            }
        }
        TestInner inner = new TestInner();
        inner.InnerMethod();
    }

    public static void main(String[] args) {
        Test test = new Test();
        test.TestMethod();
    }
}

