Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?
class One {
    String sayHello1(String name) {
        return "Hello " + name;
    }
    char[] sayHello2(String name) {
        return ("Hello " + name).toCharArray();
    }
}
public class Test {
    public static void main(String[] args) {
        One one = new One();
        Object object = one.sayHello2("OCAJP");
        if (object instanceof String)
            System.out.println("String");
        else
            System.out.println("Array");
    }
}

